-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Unternehmensformen > Einzelunternehmen
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Haftet ein Einzelunternehmer in der IT-Branche mit seinem gesamten Vermögen?', 2, '[{"text": "Ja", "correct": true, "because": "Einzelunternehmer haften unbeschränkt"}, {"text": "Nein", "correct": false, "because": "Haftung ist nicht beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Einzelunternehmen ein Mindestkapital einbringen?', 2, '[{"text": "Nein", "correct": true, "because": "Einzelunternehmen haben keine Kapitalvorgabe"}, {"text": "Ja", "correct": false, "because": "Kein Mindestkapital erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Einzelunternehmen von einer einzelnen Person geführt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Einzelunternehmen wird von einer Person geführt"}, {"text": "Nein", "correct": false, "because": "Einzelperson ist typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein IT-Einzelunternehmen verpflichtet, einen Jahresabschluss beim Bundesanzeiger zu veröffentlichen?', 2, '[{"text": "Nein", "correct": true, "because": "Einzelunternehmen haben keine Offenlegungspflicht"}, {"text": "Ja", "correct": false, "because": "Veröffentlichung nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Einzelunternehmen die Einnahmen-Überschuss-Rechnung (EÜR) zur Gewinnermittlung nutzen?', 2, '[{"text": "Ja", "correct": true, "because": "EÜR ist für Einzelunternehmer zulässig"}, {"text": "Nein", "correct": false, "because": "EÜR ist üblich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal eines IT-Einzelunternehmens?', 2, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Einzelunternehmer haften persönlich"}, {"text": "Beschränkte Haftung", "correct": false, "because": "Das gilt für GmbH"}, {"text": "Mindestkapital erforderlich", "correct": false, "because": "Kein Mindestkapital nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer führt die Geschäfte eines IT-Einzelunternehmens?', 3, '[{"text": "Der Unternehmer selbst", "correct": true, "because": "Einzelunternehmer führt allein"}, {"text": "Ein Geschäftsführer", "correct": false, "because": "Geschäftsführer bei GmbH"}, {"text": "Ein Aufsichtsrat", "correct": false, "because": "Aufsichtsrat bei AG"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Buchführungspflicht hat ein IT-Einzelunternehmen mit geringem Umsatz?', 3, '[{"text": "Einnahmen-Überschuss-Rechnung", "correct": true, "because": "EÜR für kleine Unternehmen"}, {"text": "Doppelte Buchführung", "correct": false, "because": "Nur bei höherem Umsatz"}, {"text": "Keine Buchführung", "correct": false, "because": "Mindestens EÜR erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Haftung eines IT-Einzelunternehmens?', 2, '[{"text": "Handelsgesetzbuch (HGB)", "correct": true, "because": "HGB regelt Einzelunternehmen"}, {"text": "GmbHG", "correct": false, "because": "Gilt für GmbH"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil eines IT-Einzelunternehmens?', 3, '[{"text": "Einfache Gründung", "correct": true, "because": "Keine Kapitalvorgabe oder Formalien"}, {"text": "Beschränkte Haftung", "correct": false, "because": "Haftung ist unbeschränkt"}, {"text": "Hohe Kapitalbeschaffung", "correct": false, "because": "Kapital begrenzt auf Unternehmer"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein IT-Einzelunternehmen?', 4, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Haftung mit Privatvermögen"}, {"text": "Keine Mindestkapitalvorgabe", "correct": true, "because": "Kein Kapital erforderlich"}, {"text": "Geschäftsführung durch Gesellschafter", "correct": false, "because": "Keine Gesellschafter, nur Unternehmer"}, {"text": "Einfache Gründung", "correct": true, "because": "Wenige Formalien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Einzelunternehmen für einen IT-Betrieb?', 3, '[{"text": "Einfache und kostengünstige Gründung", "correct": true, "because": "Keine Kapital- oder Notarkosten"}, {"text": "Volle Entscheidungsfreiheit", "correct": true, "because": "Unternehmer entscheidet allein"}, {"text": "Beschränkte Haftung", "correct": false, "because": "Haftung ist unbeschränkt"}, {"text": "Geringer Verwaltungsaufwand", "correct": true, "because": "Weniger Formalien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Einzelunternehmen für einen IT-Betrieb?', 4, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Privatvermögen gefährdet"}, {"text": "Eingeschränkte Kapitalbeschaffung", "correct": true, "because": "Nur eigenes Kapital"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Gründung ist kostengünstig"}, {"text": "Hoher Verwaltungsaufwand", "correct": false, "because": "Verwaltung ist einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat ein IT-Einzelunternehmen?', 3, '[{"text": "Gewerbeanmeldung", "correct": true, "because": "Pflicht bei Gewerbebetrieb"}, {"text": "Steuerliche Registrierung", "correct": true, "because": "Steuerpflicht besteht"}, {"text": "Veröffentlichung eines Jahresabschlusses", "correct": false, "because": "Keine Offenlegungspflicht"}, {"text": "Buchführung oder EÜR", "correct": true, "because": "Mindestens EÜR erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet ein Einzelunternehmen von einer GmbH für einen IT-Betrieb?', 3, '[{"text": "Unbeschränkte Haftung beim Einzelunternehmen", "correct": true, "because": "GmbH haftet beschränkt"}, {"text": "Keine Mindestkapitalvorgabe beim Einzelunternehmen", "correct": true, "because": "GmbH braucht 25.000 Euro"}, {"text": "Geschäftsführung bei Einzelunternehmen", "correct": false, "because": "Einzelunternehmer führt selbst"}, {"text": "Einfachere Gründung beim Einzelunternehmen", "correct": true, "because": "Weniger Formalien"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein IT-Einzelunternehmen haftet mit dem Privatvermögen. b) Ein Einzelunternehmen benötigt ein Mindestkapital.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein IT-Einzelunternehmen kann die EÜR nutzen. b) Ein Einzelunternehmen hat eine einfache Gründung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "EÜR und einfache Gründung sind Merkmale"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein IT-Einzelunternehmen hat keine Veröffentlichungspflicht. b) Einzelunternehmer haften beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Veröffentlichung, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Einzelunternehmen hat volle Entscheidungsfreiheit. b) Ein IT-Einzelunternehmen muss einen Geschäftsführer ernennen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entscheidungsfreiheit ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein IT-Einzelunternehmen hat keine Kapitalvorgabe. b) Einzelunternehmen sind bilanzierungspflichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Kapitalvorgabe, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

